//! `shim-sync-differential` — the control, on stdout.
//!
//! # Why a second binary and not a test
//!
//! Same reason as `shim-record` and `shim-differential`: the deliverable is an
//! artefact an analyst reads, not a property a test asserts. So the artefact is
//! generated by a binary and committed, and a test checks that the committed
//! bytes are what the binary prints today.
//!
//! # stdout, not files
//!
//! Same constraint, same reason: this crate's `std::fs` surface is empty, and
//! `tests/egress_denial.rs` proves it by scanning the source. Printing is how a
//! recording leaves the process.
//!
//! # What it prints
//!
//! ```text
//! ==== sync arm: <digest> (<label>), runs=8 ====
//! sync-differential report for the left arm
//! ==== sync arm: <digest> (<label>), runs=8 ====
//! ... right arm ...
//! ==== non-reproducible control: <digest>, runs=8 ====
//! ... the same decomposition under time=host_real, the one axis value the shim
//!     declares reproducible: false ...
//! ==== report ====
//! the committed pair's four-way decomposition
//! ```
//!
//! The three reports are what the artefact is; the arm headers exist so the
//! bytes can be split by the same `awk` rule the other two binaries use.

use std::process::ExitCode;

use shim::policy::{Axis, SubstratePolicy};
use shim::syncdiff;

fn main() -> ExitCode {
    let (left, right) = shim::differential::committed_policies();
    let n = syncdiff::COMMITTED_RUNS;

    // The committed pair, N runs per arm.
    let main = match syncdiff::run(left, right, n) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("shim-sync-differential: the arms could not be produced: {e}");
            return ExitCode::from(1);
        }
    };

    // The positive control, on the one axis value the shim itself declares
    // `reproducible: false`. Nothing here is manufactured: `time: host_real`
    // reads the host clock by design, and the shim documents that as a leak
    // worth making visible. It is the only way to show the control has power
    // without putting a coin flip into a library that has none.
    let host_real = match SubstratePolicy::default().with(Axis::Time, "host_real") {
        Ok(p) => p,
        Err(e) => {
            eprintln!("shim-sync-differential: the host_real policy was refused: {e}");
            return ExitCode::from(1);
        }
    };
    let control = match syncdiff::run(host_real, host_real, n) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("shim-sync-differential: the control arm could not be produced: {e}");
            return ExitCode::from(1);
        }
    };

    let mut out = String::new();
    out.push_str(&format!(
        "==== sync arm: {} ({}), runs={} ====\n",
        main.left.policy.digest(),
        shim::differential::arm_label(&main.left.policy),
        main.runs
    ));
    out.push_str(&arm_section(
        &main,
        &main.left,
        "committed differential, left arm",
        main.left_sync_varying(),
    ));
    out.push_str(&format!(
        "==== sync arm: {} ({}), runs={} ====\n",
        main.right.policy.digest(),
        shim::differential::arm_label(&main.right.policy),
        main.runs
    ));
    out.push_str(&arm_section(
        &main,
        &main.right,
        "committed differential, right arm",
        main.right_sync_varying(),
    ));
    out.push_str(&format!(
        "==== non-reproducible control: {} ({}) ====\n",
        control.left.policy.digest(),
        shim::differential::arm_label(&control.left.policy)
    ));
    out.push_str(&control_section(&control));

    // The same last gate the other two binaries have: no policy value may become
    // a way to get a secret into a document, and the report is a rendering of
    // documents.
    let rendered = format!("{out}{}", main.report());
    if let Err(v) = shim::redact::scrub(&rendered, &[]) {
        eprintln!("shim-sync-differential: REFUSING TO EMIT: output violates the privacy policy");
        for violation in v {
            eprintln!("  at {}: {}", violation.at, violation.what);
        }
        return ExitCode::from(2);
    }

    out.push_str("==== report ====\n");
    out.push_str(&main.report());
    print!("{out}");
    ExitCode::SUCCESS
}

/// The per-arm half of the report: what repetition alone moved, and the arm's
/// own digest so a reader can confirm the N runs really shared one policy.
fn arm_section(
    d: &syncdiff::SyncDifferential,
    arm: &syncdiff::Arm,
    title: &str,
    varying: usize,
) -> String {
    let mut o = String::new();
    o.push_str(&format!("--- {title} ---\n"));
    o.push_str(&format!(
        "policy: {} ({})\nreproducible: {}\nruns: {}\nworkload: {}\n",
        arm.policy.digest(),
        shim::differential::arm_label(&arm.policy),
        arm.policy.reproducible(),
        d.runs,
        d.workload.as_str(),
    ));
    // The N rendered documents are hashed, not printed: they are the committed
    // recordings byte for byte under a reproducible policy, so their digests are
    // a check that all N runs really produced the same thing, and printing eight
    // copies of a 73 kB document would make the artefact unreadable.
    o.push_str(&format!(
        "leaves varying across the {} identical runs: {} of {}\nrun document digests: {}\n",
        d.runs,
        varying,
        d.verdicts.len(),
        arm.rendered()
            .iter()
            .map(|r| format!("fnv1a64:{:016x}", fnv1a64(r.as_bytes())))
            .collect::<Vec<_>>()
            .join(" ")
    ));
    o
}

/// FNV-1a 64 over bytes, the same join key the policy digest uses. Not a
/// security property; it is here to say "all N of these were the same file".
fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in bytes {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

/// The control's decomposition, printed in the same shape as the main report so
/// the two can be read against each other.
/// The control's declaration, and why its numbers are not in the artefact.
///
/// This is the one place where a stable artefact and an honest report pull
/// against each other, and the report wins. The control arm reads the host
/// clock, so *which* leaves move — and how many — depends on how long each run
/// happened to take: two runs whose `SystemClock.elapsedRealtime` read lands in
/// the same millisecond produce identical documents, and a loaded machine moves
/// that boundary. Committing those counts would be committing noise and calling
/// it a result.
///
/// So the artefact states the arm, its N and its declaration, and the suite
/// carries the claim that matters: that the control detects a varying leaf, that
/// every leaf it detects is a clock fact, and that none of them is ever filed as
/// substrate-determined. Those three are stable. The count is not, and a number
/// that changes with machine load is a measurement of the machine.
fn control_section(d: &syncdiff::SyncDifferential) -> String {
    let mut o = String::new();
    o.push_str(
        "--- positive control: the same arithmetic on a substrate that is NOT reproducible ---\n",
    );
    o.push_str(&format!(
        "policy: {} ({})\nreproducible: {}\nruns: {}\nworkload: {}\n\n",
        d.left.policy.digest(),
        shim::differential::arm_label(&d.left.policy),
        d.left.policy.reproducible(),
        d.runs,
        d.workload.as_str()
    ));
    o.push_str(
        "The `time` axis is set to `host_real`, the one value whose declaration says\n\
         `reproducible: false`. It reads the host's wall clock, so no two runs are the same\n\
         document. Nothing here was manufactured: this is a property the shim already had\n\
         and already disclosed. The point is that the control detects the leaves that move,\n\
         which is what a control that reported zero everywhere would not have demonstrated.\n\n",
    );
    o.push_str(
        "  ITS COUNTS ARE DELIBERATELY NOT COMMITTED. How many leaves move depends on how long\n  \
         each run took on the machine that produced this file: two runs whose host-clock read\n  \
         lands in the same millisecond are byte-identical, and a loaded machine moves that\n  \
         boundary. The stable claims — the control finds varying leaves, every one of them is\n  \
         a clock fact, and none of them is ever filed as substrate-determined — are asserted\n  \
         in shim/tests/sync_differential.rs, where an assertion of `> 0` cannot go stale the\n  \
         way a committed integer would. A number that changes with machine load is a\n  \
         measurement of the machine, not of the substrate.\n\n",
    );
    o.push_str(&format!(
        "  This file therefore carries the arm and its declaration and nothing else about it. The\n  \
         one number that is stable — the leaf universe, {} addresses, which depends on the\n  \
         document's shape and not on its values — is printed below.\n\n",
        d.verdicts.len()
    ));
    o.push_str(
        "  A wandering leaf here lands in `both`, never in `policy_varies`, and the reason is\n  \
         the strict value-set rule: both arms read the host clock, so both value sets differ\n  \
         from each other even though no policy changed. A leaf the substrate cannot own is\n  \
         correctly not filed as substrate-determined, and correctly NOT filed as an app effect\n  \
         either. The single-run differential has no way to say that, and would have reported\n  \
         every one of them as moved and attributed it to the `time` axis — which, for a leaf\n  \
         whose value is a host timestamp, is an attribution to nothing at all.\n",
    );
    o.push_str(
        "\n  Both `policy_varies` and `sync_varies` are zero there only because the two arms are\n  \
         the SAME policy. Had they differed on some other axis, a wandering leaf would still\n  \
         land in `both`: coincidence is what that bucket is for, and no repetition removes it.\n",
    );
    o
}
